const pages={
  overview:{title:"Overview",label:"DEVELOPER PORTAL",lead:"Everything you need to build with Vedøy. Connect identity, search, AI, Canvas and Sites through one thoughtful platform."},
  quickstart:{title:"Quickstart",label:"GET STARTED",lead:"Get oriented, explore the product guides, and request access for the Vedøy capabilities that fit your project."},
  authentication:{title:"Authentication",label:"GET STARTED",lead:"A simple overview of how application credentials and user identity fit into the Vedøy platform."},
  personal:{title:"Personal Phone API",label:"API REFERENCE / PERSONAL",lead:"Privacy-first phone numbers, calls and secure messaging for people and personal products."},
  phone:{title:"Developer Portal Phone APIs",label:"API REFERENCE / COMMUNICATIONS",lead:"Search and provision numbers through Vedøy Developer Portal APIs. The Vedøy Phone app is a client that requests these APIs after sign-in."},
  business:{title:"Business Number API",label:"API REFERENCE / BUSINESS",lead:"Explore programmable numbers, routing and team communication. The included Connect server provisions Twilio numbers; shared team routing is a product preview."},
  dashboard:{title:"Business Dashboard",label:"API REFERENCE / BUSINESS",lead:"Monitor calls, usage, members and operational events from one team workspace."},
  agents:{title:"AI Agents API",label:"API REFERENCE / AI PLATFORM",lead:"Create, configure and run provider-agnostic AI agents with tools, instructions and usage controls."},
  models:{title:"Models & routing",label:"API REFERENCE / AI PLATFORM",lead:"Route requests across OpenAI, Gemini and OpenRouter while keeping your application contract stable."},
  products:{title:"Products",label:"VEDØY CORE / PRODUCTS",lead:"Choose the product surface that matches your next build."},
  services:{title:"Services",label:"VEDØY CORE / SERVICES",lead:"Composable APIs and integrations for production teams."},
  pricing:{title:"Pricing",label:"VEDØY CORE / PRICING",lead:"See what is available now, what is still a preview, and how a single Vedøy balance is intended to fund usage."},
  credits:{title:"Vedøy Credits",label:"WALLET / AI & API USAGE",lead:"One Vedøy-denominated wallet for AI and provider-backed usage, with one ledger and clear cost controls."},
  mobile:{title:"Build a phone app",label:"MOBILE / EXPO STARTER",lead:"A safe starter path for connecting iOS, Android or web apps to Vedøy Developer Portal APIs with a signed-in Supabase session."},
  maritime:{title:"Maritime Edge",label:"API REFERENCE / MARITIME",lead:"AIS, edge telemetry and operational voice for connected fleets."},
  playground:{title:"API Playground",label:"MOCK SANDBOX / VEDØY CREDITS",lead:"Explore the Vedøy API surface with safe mock responses and a transparent demo credit balance."},
  identity:{title:"Identity API",label:"API REFERENCE / IDENTITY",lead:"Identity is the foundation for sign-in, people and teams across the Vedøy ecosystem."},
  find:{title:"Find API",label:"API REFERENCE / FIND",lead:"Build search and discovery into your product with Vedøy Find."},
  ai:{title:"Vedøy AI API",label:"API REFERENCE / AI",lead:"Bring AI capabilities into your product through a Vedøy-owned, provider-agnostic interface."},
  "developer-api":{title:"Vedøy AI Developer API",label:"DEVELOPER API / BETA",lead:"Create keys, inspect the API contract and run your Vedøy agents from trusted server applications."},
  canvas:{title:"Canvas API",label:"API REFERENCE / CANVAS",lead:"Create visual workspaces for boards, frames and collaborative making."},
  sites:{title:"Sites API",label:"API REFERENCE / SITES",lead:"Work with websites and publishing flows across the Vedøy ecosystem."},
  sdks:{title:"SDKs & tools",label:"MORE / TOOLING",lead:"A home for developer tools, libraries and examples as the Vedøy platform grows."},
  changelog:{title:"Changelog",label:"MORE / UPDATES",lead:"A record of developer platform updates and API changes."},
  access:{title:"Developer access",label:"GET STARTED / EARLY ACCESS",lead:"Tell us what you’re building. Your request stays connected to your Vedøy account."}
};
const sidebar=document.querySelector("#sidebar");
const content=document.querySelector("#content-wrap");
const initialContent=content.innerHTML;
const navLinks=[...document.querySelectorAll("[data-page]")];
const breadcrumb=document.querySelector("#breadcrumb-current");
let coins=Number(localStorage.getItem("vedoy-credits-demo")||50);
function updateCoins(){document.querySelectorAll("#coin-balance,#credits-page-balance").forEach(el=>el.textContent=coins);localStorage.setItem("vedoy-credits-demo",String(coins));}
const themeToggle=document.querySelector("#theme-toggle");
function setTheme(theme){const dark=theme==="dark";document.documentElement.dataset.theme=dark?"dark":"light";document.documentElement.style.colorScheme=dark?"dark":"light";localStorage.setItem("vedoy-theme",dark?"dark":"light");if(themeToggle){themeToggle.setAttribute("aria-label",`Switch to ${dark?"light":"dark"} theme`);themeToggle.querySelector(".theme-label").textContent=dark?"Light":"Dark";themeToggle.querySelector(".theme-icon").textContent=dark?"☼":"☾";}}
setTheme(localStorage.getItem("vedoy-theme")||"light");
const mobileOverlay=document.createElement("div");mobileOverlay.className="mobile-overlay";mobileOverlay.setAttribute("aria-hidden","true");document.body.append(mobileOverlay);
document.querySelectorAll(".nav-section").forEach(section=>{const summary=section.querySelector(":scope > summary");if(!summary)return;const sync=()=>summary.setAttribute("aria-expanded",String(section.open));sync();summary.addEventListener("click",event=>{event.preventDefault();section.open=!section.open;sync();});summary.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();section.open=!section.open;sync();}});section.addEventListener("toggle",sync);});
const menuButtons=[document.querySelector("#mobile-menu"),document.querySelector("#entry-nav-toggle")].filter(Boolean);
function closeMenu(restoreFocus=false){sidebar.classList.remove("open","entry-overlay");document.body.classList.remove("nav-open");mobileOverlay.classList.remove("visible","entry-overlay");menuButtons.forEach(button=>button.setAttribute("aria-expanded","false"));if(restoreFocus)(document.querySelector("#mobile-menu")||document.querySelector("#entry-nav-toggle"))?.focus();}
function openMenu(fromEntry=false){if(fromEntry)sidebar.classList.add("entry-overlay");else sidebar.classList.remove("entry-overlay");sidebar.classList.add("open");document.body.classList.add("nav-open");mobileOverlay.classList.toggle("entry-overlay",fromEntry);mobileOverlay.classList.add("visible");menuButtons.forEach(button=>button.setAttribute("aria-expanded","true"));window.setTimeout(()=>document.querySelector("#search-input")?.focus(),120);}
menuButtons.forEach(button=>button.addEventListener("click",()=>{if(sidebar.classList.contains("open")){closeMenu();return;}if(button.id==="mobile-menu"&&window.matchMedia("(min-width: 801px)").matches){document.querySelector(".app-shell")?.classList.toggle("sidebar-collapsed");const collapsed=document.querySelector(".app-shell")?.classList.contains("sidebar-collapsed");button.setAttribute("aria-expanded",String(!collapsed));button.setAttribute("aria-label",collapsed?"Expand developer menu":"Collapse developer menu");return;}openMenu(button.id==="entry-nav-toggle");}));
mobileOverlay.addEventListener("click",()=>closeMenu());
themeToggle?.addEventListener("click",()=>setTheme(document.documentElement.dataset.theme==="dark"?"light":"dark"));
function toast(message,kind="success"){let t=document.querySelector(".portal-toast");if(!t){t=document.createElement("div");t.className="portal-toast";document.body.append(t);}t.textContent=message;t.dataset.kind=kind;t.classList.add("show");clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.remove("show"),2600);}
updateCoins();
const missionEntry=document.querySelector("#mission-entry");
missionEntry?.addEventListener("pointermove",event=>{const r=missionEntry.getBoundingClientRect();const x=(event.clientX-r.left)/r.width-.5;const y=(event.clientY-r.top)/r.height-.5;missionEntry.style.setProperty("--pointer-x",`${x*18}deg`);missionEntry.style.setProperty("--pointer-y",`${y*-14}deg`);missionEntry.style.setProperty("--glow-x",`${(x+.5)*100}%`);missionEntry.style.setProperty("--glow-y",`${(y+.5)*100}%`);});
missionEntry?.addEventListener("pointerleave",()=>{missionEntry.style.setProperty("--pointer-x","0deg");missionEntry.style.setProperty("--pointer-y","0deg");});
const missionLabels=["CHOOSE YOUR MISSION","PERSONAL COMMS","BUSINESS CONTROL","AI AGENT SYSTEMS","MARITIME SIGNALS","API COMMAND"];
const missionSlides=missionEntry?[...missionEntry.querySelectorAll("#mission-deck .swiper-slide")]:[];
let missionStep=0,missionSwiper=null;
function syncMissionScene(swiper=missionSwiper){if(!missionEntry||!swiper)return;missionStep=swiper.realIndex||0;missionEntry.classList.toggle("mission-scrolled",missionStep>0);missionEntry.classList.toggle("mission-deep-scrolled",missionStep>3);missionEntry.dataset.scene=String(missionStep);const objective=document.querySelector("#mission-objective"),step=document.querySelector("#mission-progress");if(objective)objective.textContent=missionLabels[missionStep]||missionLabels[0];if(step)step.textContent=String(missionStep+1).padStart(2,"0");}
if(missionEntry&&missionSlides.length&&window.Swiper){
  missionSwiper=new window.Swiper("#mission-deck",{direction:"vertical",slidesPerView:1,speed:window.matchMedia("(prefers-reduced-motion: reduce)").matches?0:720,loop:true,loopAdditionalSlides:1,watchSlidesProgress:true,grabCursor:true,resistanceRatio:0,mousewheel:{forceToAxis:false,sensitivity:.62,thresholdDelta:18,thresholdTime:420,releaseOnEdges:false},keyboard:{enabled:true,onlyInViewport:true,pageUpDown:false},a11y:{enabled:true,prevSlideMessage:"Previous portal scene",nextSlideMessage:"Next portal scene"},on:{init:syncMissionScene,slideChangeTransitionStart:syncMissionScene}});
  missionEntry.addEventListener("wheel",event=>{if(missionEntry.hidden)return;if(!event.target.closest("#mission-deck")){event.preventDefault();if(Math.abs(event.deltaY)>2)event.deltaY>0?missionSwiper.slideNext():missionSwiper.slidePrev();}},{passive:false});
}else if(missionEntry){missionEntry.dataset.scrollFallback="true";}
function setMissionStep(next){if(!missionSwiper)return;next>0?missionSwiper.slideNext():missionSwiper.slidePrev();}
const laptopResponse=document.querySelector("#laptop-response");
document.querySelectorAll(".api-laptop-row").forEach(row=>row.addEventListener("click",()=>{document.querySelectorAll(".api-laptop-row").forEach(x=>x.classList.remove("active"));row.classList.add("active");missionSwiper?.slideToLoop(missionSlides.length-1);if(laptopResponse)laptopResponse.textContent=JSON.stringify({status:"mock",httpStatus:Number(row.dataset.apiStatus),route:row.dataset.apiRoute,label:row.dataset.apiLabel,mode:"No production request sent"},null,2);}));
document.querySelectorAll("[data-api-open]").forEach(button=>button.addEventListener("click",()=>leaveMission("playground")));
document.querySelectorAll("[data-mission]").forEach(button=>button.addEventListener("click",()=>{document.querySelectorAll("[data-mission]").forEach(x=>x.classList.remove("selected"));button.classList.add("selected");const target=button.dataset.mission;sessionStorage.setItem("vedoy-entry-mission",target);document.querySelector("#enter-core").dataset.target=target;}));
function leaveMission(destination){missionEntry?.classList.add("exit");setTimeout(()=>{if(missionEntry)missionEntry.hidden=true;if(destination&&pages[destination]){openPage(destination);history.replaceState(null,"",`#${destination}`);window.scrollTo({top:0,behavior:"smooth"});}},620);}
document.querySelector("#enter-core")?.addEventListener("click",()=>leaveMission(document.querySelector("#enter-core")?.dataset.target||"overview"));
const apiEstimatePages=new Set(["personal","phone","business","dashboard","agents","models","maritime","identity","find","ai","canvas","sites","playground"]);
const apiEstimateProfiles={
 personal:{label:"phone actions",rate:.018,multiplier:1.2},phone:{label:"calls or messages",rate:.022,multiplier:1.35},business:{label:"business calls",rate:.016,multiplier:1.45},dashboard:{label:"tracked events",rate:.004,multiplier:.35},agents:{label:"agent runs",rate:.035,multiplier:1.8},models:{label:"model requests",rate:.028,multiplier:1.6},maritime:{label:"edge events",rate:.012,multiplier:.8},identity:{label:"identity requests",rate:.003,multiplier:.25},find:{label:"search requests",rate:.007,multiplier:.5},ai:{label:"AI requests",rate:.03,multiplier:1.7},canvas:{label:"workspace actions",rate:.006,multiplier:.4},sites:{label:"publish actions",rate:.01,multiplier:.65},playground:{label:"API requests",rate:.012,multiplier:.8}
};
function priceEstimator(key){
 const profile=apiEstimateProfiles[key]||apiEstimateProfiles.playground;
 return `<section class="api-estimator" data-price-estimator data-rate="${profile.rate}" data-multiplier="${profile.multiplier}"><div class="estimator-copy"><span class="overline">SCENARIO PLANNER</span><h2>Estimate a usage scenario</h2><p>Adjust the sample volume and workload to explore an illustrative budget. This preview is not connected to provider rates or a live Vedøy price.</p><ul><li>Interactive sample inputs</li><li>Use your workload assumptions</li><li>Check published pricing before launch</li></ul></div><div class="estimator-card"><div class="estimator-heading"><strong>Illustrative estimate</strong><span>NOT A QUOTE</span></div><label><span>Monthly ${profile.label}</span><output data-estimate-volume>1,000</output><input data-estimate-input="volume" type="range" min="100" max="50000" step="100" value="1000" /></label><label><span>Average workload</span><output data-estimate-workload>5</output><input data-estimate-input="workload" type="range" min="1" max="30" step="1" value="5" /></label><label><span>Sample cost input ($/hour)</span><output data-estimate-wage>35</output><input data-estimate-input="wage" type="range" min="10" max="100" step="1" value="35" /></label><div class="estimate-results"><div><small>Illustrative API scenario</small><strong data-estimate-api>$0</strong></div><div><small>Your manual benchmark input</small><strong data-estimate-manual>$0</strong></div></div><div class="estimate-saving"><small>Illustrative difference · not savings</small><strong data-estimate-saving>$0</strong></div><p>Example math only. No verified Vedøy tariff, provider rate, tax or contract price is applied.</p></div></section>`;
}
function developerApiDemo(){return `<div class="developer-console-demo"><div class="developer-demo-head"><div><span class="overline">DEVELOPER API / BETA</span><h2>Your agents. <em>In your stack.</em></h2><p>API keys, OpenAPI and server-side examples now live in Vedøy Developer Portal. This static demo never creates a real key.</p></div><span class="service-state">Preview</span></div><div class="developer-demo-grid"><div><h3>01 · Access</h3><label>Key name<input class="endpoint-input" value="My application" aria-label="Demo key name" /></label><button class="button-primary" type="button" data-demo-key>Create demo key <span>+</span></button><p class="demo-note">Demo only · store real secrets on your server.</p></div><div><h3>02 · Quick start</h3><pre>curl https://vedoy-ai.vercel.app/api/v1/agents \\\n  -H "Authorization: Bearer $VEDOY_API_KEY"</pre><a class="doc-cta" href="https://vedoy-ai.vercel.app/api/v1/openapi.json" target="_blank" rel="noreferrer">OpenAPI 3.1 specification ↗</a></div></div></div>`;}
function cssStudioDemo(){return `<section class="css-studio-demo"><span class="overline">VEDØY CSS / COMPONENT LAB</span><h2>Build the interface layer.</h2><p>Choose a ready-made Vedøy CSS surface for your next product.</p><div class="css-demo-buttons"><button type="button" class="button-primary">Vedøy CSS Core <span>↗</span></button><button type="button" class="button-dark">Vedøy CSS Dark <span>↗</span></button></div><button type="button" class="css-coming-soon" disabled>Vedøy CSS Studio <span>coming soon</span></button></section>`;}
function docBody(key){
 const p=pages[key]||pages.overview;
 const examples={
 products:`<div class="product-page-grid"><div class="doc-mini-card"><strong>Personal Phone</strong><p>Extra numbers, private calls and secure SMS.</p><a class="doc-cta" href="#personal" data-page="personal">Explore product →</a></div><div class="doc-mini-card"><strong>Business Communications</strong><p>Shared numbers, routing and usage controls.</p><a class="doc-cta" href="#business" data-page="business">Explore product →</a></div><div class="doc-mini-card"><strong>AI Agents</strong><p>Agents, tools, model routing and spend controls.</p><a class="doc-cta" href="#agents" data-page="agents">Explore product →</a></div><div class="doc-mini-card"><strong>Maritime Edge</strong><p>AIS, voice and edge data for real operations.</p><a class="doc-cta" href="#maritime" data-page="maritime">Explore product →</a></div></div>`,
 services:`<div class="product-page-grid"><div class="doc-mini-card"><strong>APIs</strong><p>OpenAPI contracts and a local mock playground.</p><a class="doc-cta" href="#playground" data-page="playground">Open playground →</a></div><div class="doc-mini-card"><strong>Agent Studio</strong><p>Create and manage agents in the Vedøy AI workspace.</p><a class="doc-cta" href="https://vedoy-ai.vercel.app/workspace">Open Agent Studio ↗</a></div><div class="doc-mini-card"><strong>Supabase integrations</strong><p>Auth, persistence and secure user-owned data flows.</p><span class="service-state">Available with integration</span></div><div class="doc-mini-card"><strong>Vercel deployment</strong><p>Edge-ready static sites and production deployment workflows.</p><span class="service-state">Available with integration</span></div></div>`,
 pricing:`<div class="pricing-intro"><span class="availability-badge preview-badge">Preview · no live checkout</span><p>We are not publishing fixed phone or AI prices until provider rates, taxes, number rent and the service margin are verified. This keeps estimates from looking like a billable offer.</p></div><div class="pricing-grid"><article class="pricing-card"><span class="pricing-tag">DEVELOPER SANDBOX</span><h2>$0<span> / to explore</span></h2><p>Use the portal’s local examples to learn the API shapes.</p><ul><li>Mock responses only</li><li>50 browser-only demo credits</li><li>No carrier or model calls</li></ul><span class="service-state">Available · demo</span><a class="button-primary" href="#playground" data-page="playground">Open safe sandbox</a></article><article class="pricing-card featured"><span class="pricing-tag">VEDØY CREDITS</span><h2>One wallet<span> · planned</span></h2><p>One Vedøy balance for AI and connected services.</p><ul><li>Model usage based on provider cost</li><li>Calls, SMS and number rent metered</li><li>Budget caps before provider calls</li></ul><span class="service-state">Wallet preview · not purchasable</span><a class="button-primary" href="#credits" data-page="credits">How credits work</a></article><article class="pricing-card"><span class="pricing-tag">BUSINESS</span><h2>Usage-based<span> · planned</span></h2><p>For products with team numbers and recurring traffic.</p><ul><li>Provider costs itemized</li><li>Workspace limits and alerts</li><li>Monthly usage export</li></ul><span class="service-state">Quote after rates are verified</span><a class="button-primary" href="#access" data-page="access">Discuss a use case</a></article><article class="pricing-card"><span class="pricing-tag">ENTERPRISE</span><h2>Talk to us</h2><p>For dedicated routing, compliance and edge deployments.</p><ul><li>Custom deployment review</li><li>Availability and residency checked</li><li>Contracted limits and support</li></ul><span class="service-state">Contact · no public price</span><a class="button-primary" href="mailto:hello@vedoystudio.no?subject=Ved%C3%B8y%20Core%20pricing">Request a quote</a></article></div><section class="pricing-breakdown"><span class="overline">HOW FUTURE BILLING SHOULD WORK</span><div><strong>1. Provider cost</strong><p>Actual model tokens, carrier calls/SMS and rented numbers come from their provider invoices.</p></div><div><strong>2. Vedøy Credits</strong><p>Usage is reserved and posted to one account ledger in a clear Vedøy unit before it can exceed its budget.</p></div><div><strong>3. Clear receipts</strong><p>Each charge names the product, unit, provider cost, Vedøy fee and remaining balance.</p></div></section><p class="pricing-note">No Stripe checkout, live provider metering, posted unit rate or production customer billing is enabled by this static portal today. Nothing here is a final offer.</p>`,
 credits:`<section class="credits-overview"><div class="credits-balance-card"><span class="overline">LOCAL DEMO WALLET</span><strong><span id="credits-page-balance">50</span> <small>Vedøy Credits</small></strong><p>This balance is stored in this browser only. It is not account-backed, transferable, redeemable, or usable with live APIs.</p><span class="service-state">Demo · no purchase available</span></div><div class="credits-explainer"><span class="overline">ONE VEDØY UNIT</span><h2>One balance. Connected services.</h2><p>Vedøy Credits are planned as a common display and budget unit. Vedøy would pay connected providers behind the scenes, then show customers the service, usage, conversion and remaining budget in one ledger.</p><ul><li>AI: show model and token usage</li><li>Phone: itemize calls, SMS and number rent</li><li>Control: monthly budgets, alerts and a pause switch</li></ul></div></section><div class="doc-callout"><strong>Current status:</strong> the browser balance and simulated API deductions are a local demo. They do not sync to Vedøy accounts or call Stripe, Supabase billing, AI providers, Twilio or Telnyx. Do not use them to estimate an invoice.</div><h2>How to build with the real Phone app</h2><p>See the Phone developer guide and mobile repository for the real app/API contract. Its API service still needs a confirmed public deployment and provider credentials before customer traffic can be billed.</p><p><a class="doc-cta" href="https://vedoy-phone.vercel.app/developers/" target="_blank" rel="noreferrer">Vedøy Phone developer guide ↗</a> &nbsp; <a class="doc-cta" href="https://github.com/leandervedoy/vedoy-phone" target="_blank" rel="noreferrer">Mobile app repository ↗</a></p><h2>Before selling credits</h2><p>Set a published EUR/NOK conversion, define refunds and expiry, persist an auditable server-side ledger, reserve funds atomically before provider requests, reconcile failed calls, and verify tax and consumer terms.</p>`,
 mobile:`<div class="mobile-readiness-banner"><span class="service-state">Mobile project exists · API deployment unconfirmed</span><p>Vedøy Phone is the app and communications API project. This portal provides the discovery and integration guide; it is not itself a phone app or API server.</p><a class="button-primary" href="https://vedoy-phone.vercel.app/developers/" target="_blank" rel="noreferrer">Open Phone developer guide ↗</a></div><h2>Connect an iOS or Android app</h2><ol class="mobile-steps"><li><strong>Use the existing Expo app</strong><p>Start from the Vedøy Phone repository and its setup instructions. Use an Expo development build for Twilio Voice; Expo Go does not support the native calling module.</p></li><li><strong>Configure the real API origin</strong><p>Set <code>EXPO_PUBLIC_API_URL</code> to the confirmed HTTPS origin of the separately deployed Node API. The sample <code>api.vedoy.example</code> is a placeholder, not a working host.</p></li><li><strong>Authenticate every request</strong><p>Get the signed-in Supabase session access token and send it as <code>Authorization: Bearer &lt;access_token&gt;</code>. Never put service-role keys, Twilio secrets or provider credentials in the app.</p></li></ol><h2>Verified request shapes</h2><pre>// Expo app — require a signed-in user\nconst { data: { session } } = await supabase.auth.getSession();\nconst response = await fetch(API_URL + "/v1/messages", {\n  method: "POST",\n  headers: { "Authorization": "Bearer " + session.access_token, "Content-Type": "application/json" },\n  body: JSON.stringify({ to: "+4790000000", body: "Hello" })\n});</pre><pre>// Request a short-lived calling token\nawait fetch(API_URL + "/v1/voice/token", {\n  method: "POST",\n  headers: { "Authorization": "Bearer " + session.access_token, "Content-Type": "application/json" },\n  body: JSON.stringify({ platform: "ios" })\n});</pre><p><a class="doc-cta" href="https://github.com/leandervedoy/vedoy-phone#readme" target="_blank" rel="noreferrer">Open setup and server notes ↗</a> &nbsp; <a class="doc-cta" href="#phone" data-page="phone">Browse Phone API endpoints →</a></p><div class="doc-callout"><strong>Production check:</strong> Vercel currently serves the Phone developer website. That does not confirm the Node communications API is deployed. Set up the API service, Supabase project, Twilio credentials and inbound-call push credentials before expecting live calls or SMS.</div>`,
 maritime:`<div class="doc-callout"><strong>Maritime Edge.</strong> Build AIS, operational voice and telemetry workflows for fleets, ports and edge devices.</div><h2>Edge primitives</h2><table class="doc-table"><thead><tr><th>ENDPOINT</th><th>USE</th></tr></thead><tbody><tr><td><code>GET /v1/ais/radar</code></td><td>Live vessel positions</td></tr><tr><td><code>POST /v1/voice/ptt/rooms</code></td><td>Push-to-talk rooms</td></tr><tr><td><code>POST /v1/telemetry/geofences</code></td><td>Operational alerts</td></tr></tbody></table><p><a class="doc-cta" href="#playground" data-page="playground">Try the sandbox →</a></p>`,
 personal:`<div class="doc-callout"><strong>Personal privacy layer.</strong> The existing Vedøy Phone project documents numbers, calls, SMS and account-owned history. Its public API host and production readiness still need confirmation.</div><h2>Personal endpoints</h2><div class="doc-columns"><div class="doc-mini-card"><strong>Find and buy a number</strong><p>Search provider inventory and review country pricing before purchase.</p><code>GET /v1/numbers/available</code><br/><code>POST /v1/numbers/purchase</code></div><div class="doc-mini-card"><strong>Secure calls &amp; SMS</strong><p>Send an SMS or request a short-lived Voice token with the signed-in user's API session.</p><code>POST /v1/messages</code><br/><code>POST /v1/voice/token</code></div></div><p><a class="doc-cta" href="#phone" data-page="phone">Open Vedøy Phone API guide →</a> &nbsp; <a class="doc-cta" href="#playground" data-page="playground">Explore local mock examples →</a></p>`,
 phone:`<div class="doc-callout"><strong>Use the existing Vedøy Phone API guide.</strong> It documents Voice, two-way SMS, number search and purchase, KYC and webhook flows backed by Supabase JWTs and Twilio. The guide currently shows <code>https://api.vedoy.example</code> as an example host, so replace it only after the real Connect API URL is confirmed. The Phone web app itself is not the API host.</div><p><a class="doc-cta" href="https://vedoy-phone.vercel.app/developers/" target="_blank" rel="noreferrer">Open Vedøy Phone developer guide ↗</a> &nbsp; <a class="doc-cta" href="https://github.com/leandervedoy/vedoy-phone#readme" target="_blank" rel="noreferrer">Read Phone README ↗</a></p><h2>Phone API surface</h2><div class="endpoint-list"><div class="endpoint-row"><span class="method post">POST</span><code>/v1/voice/token</code><span>Short-lived Twilio Voice token for iOS/Android builds</span></div><div class="endpoint-row"><span class="method">GET</span><code>/v1/voice/history</code><span>Signed-in user's call events</span></div><div class="endpoint-row"><span class="method">GET</span><code>/v1/messages/threads</code><span>Inbox thread list</span></div><div class="endpoint-row"><span class="method">GET</span><code>/v1/messages/threads/:phone</code><span>Chronological thread for an E.164 number</span></div><div class="endpoint-row"><span class="method post">POST</span><code>/v1/messages</code><span>Send SMS with allowlist, rate and opt-out checks</span></div><div class="endpoint-row"><span class="method">GET</span><code>/v1/numbers/countries</code><span>Country and policy catalog</span></div><div class="endpoint-row"><span class="method">GET</span><code>/v1/numbers/available</code><span>Search provider inventory</span></div><div class="endpoint-row"><span class="method post">POST</span><code>/v1/numbers/purchase</code><span>Price re-check, quota lock and KYC gate</span></div><div class="endpoint-row"><span class="method post">POST</span><code>/v1/kyc/submissions</code><span>Register uploaded KYC documents</span></div><div class="endpoint-row"><span class="method">GET</span><code>/v1/kyc/status</code><span>Check your review status</span></div></div><h2>Before calling it from the app</h2><div class="doc-columns provider-readiness"><article class="doc-mini-card"><span class="core-card-index">AUTH / SUPABASE JWT</span><strong>Authenticate the person</strong><p>Get the current Supabase session token and send it as <code>Authorization: Bearer …</code>. The phone API guide says all <code>/v1</code> routes require this JWT.</p></article><article class="doc-mini-card"><span class="core-card-index">DEPLOY / NOT CONFIRMED</span><strong>Get the real API origin</strong><p>The Phone developers page says the backend is implemented locally but not confirmed deployed from that project, and its sample origin is explicitly a placeholder. A real Vercel/API deployment and Twilio credentials are still required.</p></article></div><p><a class="doc-cta" href="#mobile" data-page="mobile">Open the mobile app starter →</a></p>`,
 business:`<div class="doc-callout"><strong>Business communications.</strong> Give teams a shared number, routing rules and auditable usage.</div><h2>Business number building blocks</h2><div class="doc-columns"><div class="doc-mini-card"><strong>Numbers &amp; routing</strong><p>Assign numbers to teams, schedules and IVR flows.</p></div><div class="doc-mini-card"><strong>Usage &amp; billing</strong><p>Track minutes, messages, limits and cost centres.</p></div></div><pre>// Preview shape\nconst number = await vedoy.business.numbers.provision({ region: "NO" });</pre>`,
 dashboard:`<div class="doc-callout"><strong>One operational view.</strong> Bring members, numbers, call activity, quotas and audit events together.</div><h2>Dashboard modules</h2><ul class="readiness-list"><li><span>01</span><div><strong>Live usage</strong><p>Calls, SMS, API requests and spend by workspace.</p></div></li><li><span>02</span><div><strong>Team controls</strong><p>Roles, number assignments and approval policies.</p></div></li><li><span>03</span><div><strong>Audit trail</strong><p>Exportable events for operations and compliance.</p></div></li></ul>`,
 agents:`<div class="doc-callout"><strong>AI agents are a first-class API product.</strong> Define instructions, tools, model routing, limits and handoffs behind a stable Vedøy interface.</div><h2>Agent lifecycle</h2><div class="doc-columns"><div class="doc-mini-card"><strong>Create</strong><p><code>POST /v1/agents</code><br/>Save a versioned agent.</p></div><div class="doc-mini-card"><strong>Run</strong><p><code>POST /v1/agents/:id/runs</code><br/>Start a tracked run.</p></div><div class="doc-mini-card"><strong>Observe</strong><p>Inspect latency, tokens, errors and spend.</p></div></div><p><a class="doc-cta" href="https://vedoy-ai.vercel.app/workspace">Open Agent Studio ↗</a></p>`,
 models:`<div class="doc-callout"><strong>Provider-agnostic routing.</strong> Keep your product contract stable while choosing OpenAI, Gemini or OpenRouter per task or budget.</div><h2>Routing controls</h2><table class="doc-table"><thead><tr><th>CONTROL</th><th>WHY IT MATTERS</th></tr></thead><tbody><tr><td><code>model</code></td><td>Choose a verified provider model</td></tr><tr><td><code>fallbacks</code></td><td>Recover from provider errors</td></tr><tr><td><code>budget</code></td><td>Stop runaway spend</td></tr></tbody></table>`,
 playground:`<div class="playground-head"><div><span class="overline">MOCK API SANDBOX</span><h2>Try the platform contracts</h2><p>Every request below is simulated locally so you can explore payloads without sending production traffic. Each run uses demo Vedøy Credits stored in this browser.</p></div><button class="button-primary" type="button" data-topup>Credits overview ↗</button></div><div class="endpoint-grid"><article class="endpoint-card" data-endpoint="burner" data-cost="5"><div class="endpoint-meta"><span class="method post">POST</span><code>/v1/phone/burner</code><span class="cost">5 credits</span></div><h3>Generate Burner Number</h3><p>Create a simulated disposable +47 number for privacy-first flows.</p><button class="endpoint-run" type="button">Run mock API <span>→</span></button><pre class="endpoint-result" aria-live="polite">Ready to run</pre></article><article class="endpoint-card" data-endpoint="sms" data-cost="1"><div class="endpoint-meta"><span class="method post">POST</span><code>/v1/sms/send</code><span class="cost">1 credit</span></div><h3>Send Secure SMS</h3><input class="endpoint-input" placeholder="+47 900 00 000" aria-label="Phone number" /><input class="endpoint-input" placeholder="Your secure message" aria-label="Message" /><button class="endpoint-run" type="button">Send mock request <span>→</span></button><pre class="endpoint-result" aria-live="polite">Ready to run</pre></article><article class="endpoint-card" data-endpoint="esim" data-cost="10"><div class="endpoint-meta"><span class="method post">POST</span><code>/v1/esim/data</code><span class="cost">10 credits</span></div><h3>Provision Global eSIM</h3><p>Preview an illustrative 1GB data-plan response; no plan is provisioned.</p><button class="endpoint-run" type="button">Run mock API <span>→</span></button><pre class="endpoint-result" aria-live="polite">Ready to run</pre></article><article class="endpoint-card" data-endpoint="sip" data-cost="15"><div class="endpoint-meta"><span class="method post">POST</span><code>/v1/sip/trunk</code><span class="cost">15 credits</span></div><h3>SIP Trunk Provisioning</h3><select class="endpoint-input" aria-label="Region"><option>Europe</option><option>USA</option><option>Asia</option></select><button class="endpoint-run" type="button">Run mock API <span>→</span></button><pre class="endpoint-result" aria-live="polite">Ready to run</pre></article><article class="endpoint-card" data-endpoint="ivr" data-cost="2"><div class="endpoint-meta"><span class="method put">PUT</span><code>/v1/ivr/flow</code><span class="cost">2 credits</span></div><h3>IVR Flow Builder</h3><p class="flow-pills"><button type="button" class="flow-pill active">1 · Sales</button><button type="button" class="flow-pill">2 · Support</button></p><button class="endpoint-run" type="button">Run mock API <span>→</span></button><pre class="endpoint-result" aria-live="polite">Ready to run</pre></article><article class="endpoint-card" data-endpoint="ais" data-cost="3"><div class="endpoint-meta"><span class="method get">GET</span><code>/v1/ais/radar</code><span class="cost">3 credits</span></div><h3>X-Band AIS Radar</h3><div class="radar-preview"><i></i><b></b><b></b><b></b></div><button class="endpoint-run" type="button">Run mock API <span>→</span></button><pre class="endpoint-result" aria-live="polite">Ready to run</pre></article></div><p class="playground-note">All responses are mock data. Credits here are a local demo counter, not a purchasable balance or live usage meter.</p>`,
 quickstart:`<div class="doc-callout"><strong>Know what is live.</strong> Agent Studio is available as a web app. The public APIs and SDKs described here are previews; no production endpoint or API key is being offered by this guide.</div><h2>Your first 10 minutes</h2><div class="quickstart-steps"><article><span>01 / EXPLORE</span><strong>Pick a product</strong><p>Open Identity, Find, AI, Canvas or Sites to review the capability and its current status.</p></article><article><span>02 / BUILD</span><strong>Try Agent Studio</strong><p>Create and chat with an agent in the workspace. Sign in with your Vedøy account.</p><a href="https://vedoy-ai.vercel.app/workspace">Open Agent Studio ↗</a></article><article><span>03 / CONNECT</span><strong>Request API access</strong><p>Tell us what you are building. The team can confirm availability, credentials and integration requirements.</p><a href="#access" data-page="access">Request access →</a></article></div><h2>Production readiness checklist</h2><ul class="readiness-list"><li><span>✓</span><div><strong>Keep credentials on your server</strong><p>Never ship secret keys in browser JavaScript, mobile bundles or public repositories.</p></div></li><li><span>✓</span><div><strong>Confirm the contract first</strong><p>Get the production base URL, auth method, scopes, rate limits and error format from the Vedøy team.</p></div></li><li><span>✓</span><div><strong>Plan for change</strong><p>Ask about versioning, deprecation notices, data retention and support before launching to customers.</p></div></li></ul><p><a class="doc-cta" href="#access" data-page="access">Tell us about your integration →</a></p>`,
 authentication:`<div class="doc-callout"><strong>Developer hub sign-in.</strong> The hub uses the existing Vedøy account pool in the Vedoy Supabase project. Create a new account through <a href="https://vedoy-oauth.vercel.app" target="_blank" rel="noreferrer">Vedøy OAuth</a>, then sign in here with that account.</div><h2>Profile data</h2><p>After sign-in, the hub reads the current user's display name from <code>public.vedoy_profiles</code>. Row Level Security limits that lookup to the signed-in user's own profile.</p><h2>API credentials</h2><p>Application API keys are separate from your Vedøy account. Keep secret API credentials on trusted servers and out of browser code.</p><h2>Session controls</h2><p>Use the account button in the header to view your signed-in identity or end the session. Sessions are stored by the Supabase client and refreshed automatically.</p>`,
 identity:`<div class="doc-callout"><strong>In development.</strong> This page describes the product surface. Endpoint paths, scopes and availability need confirmation before implementation.</div><h2>What you can build</h2><div class="doc-columns"><div class="doc-mini-card"><strong>Sign in</strong><p>Give people a consistent way to access connected Vedøy products.</p></div><div class="doc-mini-card"><strong>People &amp; teams</strong><p>Model the people and collaborative spaces around a product.</p></div></div><h2>Integration concepts</h2><table class="doc-table"><thead><tr><th>CONCEPT</th><th>DESCRIPTION</th></tr></thead><tbody><tr><td><code>Identity</code></td><td>Accounts and authentication</td></tr><tr><td><code>Workspace</code></td><td>A shared context for people and projects</td></tr><tr><td><code>Consent</code></td><td>Explicit user control over connected services</td></tr></tbody></table><h2>Example shape</h2><pre>// Preview only — confirm the current SDK and endpoint first\nconst session = await vedoy.identity.getSession();</pre>`,
 find:`<div class="doc-callout"><strong>In development.</strong> The examples are conceptual. Confirm indexing rules, data permissions and available endpoints before integrating.</div><h2>Search that fits your product</h2><p>Vedøy Find is intended to connect relevant content and products through a discovery layer. Design your experience around the content you are allowed to expose.</p><h2>Core concepts</h2><table class="doc-table"><thead><tr><th>CONCEPT</th><th>USE IT FOR</th></tr></thead><tbody><tr><td><code>Sources</code></td><td>Choosing which content can be discovered</td></tr><tr><td><code>Query</code></td><td>Searching with user intent in mind</td></tr><tr><td><code>Results</code></td><td>Returning useful, permission-aware matches</td></tr></tbody></table><h2>Example shape</h2><pre>// Preview only — API shape may change\nconst results = await vedoy.find.search({ query: "..." });</pre>`,
 ai:`<div class="doc-callout"><strong>Provider-agnostic by design.</strong> The Agent Studio app is available. Public API endpoints and SDKs are still in preview; request access before integrating.</div><h2>Build with Vedøy AI</h2><p>Keep your application connected to a Vedøy-owned interface, so product logic can stay separate from the underlying AI provider.</p><div class="agent-callout"><div><span class="agent-status-mark"></span><strong>Agent Studio</strong><p>Create prompt-based agents, choose an available model, edit instructions, and save conversations to your Vedøy account.</p></div><a class="agent-launch" href="https://vedoy-ai.vercel.app/workspace">Open Agent Studio <span>↗</span></a></div><h2>What agents can do today</h2><div class="doc-columns"><div class="doc-mini-card"><strong>Configure &amp; save</strong><p>Create, copy, edit, and remove private agents. Agent settings and conversations are stored against the signed-in account.</p></div><div class="doc-mini-card"><strong>Chat with a model</strong><p>Run text conversations through the configured provider gateway with a daily request limit and usage records.</p></div><div class="doc-mini-card"><strong>Current boundary</strong><p>Agents do not yet run external tools, keep long-term memory, or hand tasks to other agents. LiteLLM routing is available when the gateway is configured.</p></div><div class="doc-mini-card"><strong>Integration status</strong><p>Use the workspace directly today. The public Vedøy AI API example below is illustrative and is not a live endpoint.</p></div></div><h2>Example shape</h2><pre>// Preview only — public API endpoint is not released\nconst answer = await vedoy.ai.generate({ prompt: "..." });</pre>`,
 canvas:`<div class="doc-callout"><strong>Canvas boundary.</strong> Canvas boards and frames are distinct from Vedøy Bøker and Sites. Treat each as its own product surface.</div><h2>Bring a canvas into your workflow</h2><p>Canvas is for visual thinking and collaborative making. Boards hold a working space; frames help give structure to that space.</p><table class="doc-table"><thead><tr><th>OBJECT</th><th>ROLE</th></tr></thead><tbody><tr><td><code>Board</code></td><td>A canvas workspace</td></tr><tr><td><code>Frame</code></td><td>A named region inside a board</td></tr><tr><td><code>Member</code></td><td>A collaborator with workspace access</td></tr></tbody></table><h2>Example shape</h2><pre>// Preview only — confirm scopes and endpoint first\nconst board = await vedoy.canvas.createBoard({ title: "Ideas" });</pre>`,
 sites:`<div class="doc-callout"><strong>In development.</strong> Publishing requirements, domain setup and endpoint support depend on the current Sites service.</div><h2>Websites in the Vedøy ecosystem</h2><p>Use Sites to build and publish web experiences with a workflow designed for the platform.</p><h2>Publishing concepts</h2><table class="doc-table"><thead><tr><th>CONCEPT</th><th>DESCRIPTION</th></tr></thead><tbody><tr><td><code>Site</code></td><td>A website project with its own identity</td></tr><tr><td><code>Deployment</code></td><td>A published version of a site</td></tr><tr><td><code>Domain</code></td><td>The address where a site is available</td></tr></tbody></table><h2>Keep ownership clear</h2><p>Vedøy Sites are standalone websites. They are not book embeds or Canvas boards.</p>`,
 sdks:`<div class="doc-callout"><strong>Coming together.</strong> This hub is the home for official SDKs and tools. Package names and support status will appear here when verified.</div><h2>Tooling principles</h2><div class="doc-columns"><div class="doc-mini-card"><strong>Official first</strong><p>Use libraries published and supported by Vedøy.</p></div><div class="doc-mini-card"><strong>Clear status</strong><p>Examples should say when they are previews or community maintained.</p></div></div><h2>In the meantime</h2><p>Use the API reference pages to explore product concepts. Contact the Vedøy team if you need current integration guidance.</p>`,
 changelog:`<div class="doc-callout"><strong>Developer preview.</strong> No public API release history has been published.</div><h2>Updates will live here</h2><p>Verified changes will be listed here with dates, availability, behavior changes and migration guidance.</p>`,
 access:`<div class="doc-callout"><strong>Early access.</strong> Public API endpoints are not available yet. Submit a request to discuss your project with the Vedøy team.</div><section class="access-panel"><div id="access-auth-gate" class="access-gate"><h2>Sign in to request access</h2><p>Requests are linked to your Vedøy account so you can see their status here.</p><button class="button-primary" type="button" data-open-auth>Sign in with Vedøy <span>↗</span></button><p class="auth-register">New to Vedøy? <a href="https://vedoy-oauth.vercel.app" target="_blank" rel="noreferrer">Create an account ↗</a></p></div><form id="access-form" class="access-form" hidden><label for="access-organization">Organization or project name</label><input id="access-organization" name="organization" required minlength="2" maxlength="120" autocomplete="organization" /><label for="access-website">Project website <span>(optional)</span></label><input id="access-website" name="website" type="url" maxlength="500" placeholder="https://example.com" autocomplete="url" /><fieldset><legend>What are you interested in?</legend><label><input type="checkbox" name="products" value="identity" /> Identity</label><label><input type="checkbox" name="products" value="find" /> Find</label><label><input type="checkbox" name="products" value="ai" /> Vedøy AI</label><label><input type="checkbox" name="products" value="canvas" /> Canvas</label><label><input type="checkbox" name="products" value="sites" /> Sites</label></fieldset><label for="access-use-case">What are you building?</label><textarea id="access-use-case" name="use_case" required minlength="30" maxlength="3000" rows="5" placeholder="Describe your product, who it helps, and how you’d like to use Vedøy."></textarea><p class="access-privacy">Your request is visible only to your account and authorized Vedøy team members. Do not include secrets or personal data about other people. See Vedøy’s <a href="https://vedoy-oauth.vercel.app/policies#privacy" target="_blank" rel="noreferrer">Privacy Policy</a>.</p><div id="access-message" class="auth-message" role="status" aria-live="polite"></div><button class="button-primary" id="access-submit" type="submit">Send access request <span>→</span></button></form><div id="access-history" class="access-history" hidden></div></section>`
 };
 examples.phone=`<div class="doc-callout"><strong>Developer Portal owns the API layer.</strong> Vedøy Phone is a client app. It signs users in and requests Voice, two-way SMS, number search, purchase, KYC and webhook-backed actions from these Developer Portal APIs.</div><section class="phone-provisioner" data-phone-provisioner><div class="phone-provisioner-copy"><span class="overline">NUMBER INVENTORY</span><h2>Choose your number.</h2><p>Availability, recurring carrier price and capabilities are fetched from the Developer Portal API for the selected country.</p><p class="phone-live-state" data-phone-state>Checking Developer Portal API…</p></div><form class="phone-search-form" data-phone-search><label>Country<select name="country"><option value="NO">Norway</option><option value="SE">Sweden</option><option value="DK">Denmark</option><option value="FI">Finland</option><option value="GB">United Kingdom</option><option value="US">United States</option></select></label><label>Number type<select name="type"><option value="local">Local</option><option value="mobile">Mobile</option><option value="tollFree">Toll-free</option></select></label><button class="button-primary" type="submit">Find numbers <span>→</span></button></form><div class="phone-number-results" data-phone-results aria-live="polite"><p>Sign in from Vedøy Phone or the portal, then search available numbers.</p></div></section><h2>Live endpoints</h2><div class="endpoint-list"><div class="endpoint-row"><span class="method">GET</span><code>/v1/numbers/available</code><span>Search account-scoped carrier inventory</span></div><div class="endpoint-row"><span class="method post">POST</span><code>/v1/numbers/purchase</code><span>Confirm a current monthly price, then provision</span></div><div class="endpoint-row"><span class="method post">POST</span><code>/v1/messages</code><span>Send SMS from an owned active line</span></div><div class="endpoint-row"><span class="method post">POST</span><code>/v1/voice/token</code><span>Get a short-lived native calling token</span></div></div><p><a class="doc-cta" href="https://vedoy-phone.vercel.app/developers/" target="_blank" rel="noreferrer">Vedøy Phone app guide ↗</a> &nbsp; <a class="doc-cta" href="https://github.com/leandervedoy/vedoy-phone#readme" target="_blank" rel="noreferrer">Source and mobile app ↗</a></p>`;
examples.mobile=`<div class="mobile-readiness-banner"><span class="service-state">Phone app exists · Developer Portal APIs are the backend</span><p>Vedøy Phone is the customer app. It signs the user in, then requests numbers, SMS and calling tokens from Vedøy Developer Portal APIs.</p><a class="button-primary" href="https://vedoy-phone.vercel.app/developers/" target="_blank" rel="noreferrer">Open Phone app guide ↗</a></div><h2>Connect an iOS or Android app</h2><ol class="mobile-steps"><li><strong>Use the existing Expo app</strong><p>Start from the Vedøy Phone repository and use an Expo development build for Twilio Voice. Expo Go does not support the native calling module.</p></li><li><strong>Configure the Developer Portal API origin</strong><p>Set <code>EXPO_PUBLIC_API_URL</code> to the public Vedøy Developer Portal API origin. Today that origin is <code>https://vedoy-phone-api.vercel.app</code> while the communications API service is being finalized.</p></li><li><strong>Authenticate every request</strong><p>Get the signed-in Supabase session access token and send it as <code>Authorization: Bearer &lt;access_token&gt;</code>. Service-role keys, Twilio secrets and provider credentials stay on the API server only.</p></li><li><strong>Test on a real device</strong><p>Outbound SMS can be tested after Twilio messaging is configured. Inbound calls require the Twilio Voice app, TwiML app webhooks and APNs or Firebase push credentials.</p></li></ol><h2>Verified request shapes</h2><pre>const API_URL = "https://vedoy-phone-api.vercel.app";\nconst { data: { session } } = await supabase.auth.getSession();\n\nawait fetch(API_URL + "/v1/messages", {\n  method: "POST",\n  headers: { "Authorization": "Bearer " + session.access_token, "Content-Type": "application/json" },\n  body: JSON.stringify({ to: "+4790000000", body: "Hello from Vedoy" })\n});</pre><pre>await fetch(API_URL + "/v1/voice/token", {\n  method: "POST",\n  headers: { "Authorization": "Bearer " + session.access_token, "Content-Type": "application/json" },\n  body: JSON.stringify({ platform: "ios" })\n});</pre><p><a class="doc-cta" href="https://github.com/leandervedoy/vedoy-phone#readme" target="_blank" rel="noreferrer">Open app setup notes ↗</a> &nbsp; <a class="doc-cta" href="#phone" data-page="phone">Browse Developer Portal Phone APIs →</a></p><div class="doc-callout"><strong>Current production state:</strong> the Developer Portal API origin is public and responds, but reports setup required until <code>SUPABASE_SERVICE_ROLE_KEY</code> and the Twilio credentials are configured. Vedøy Phone must show this as setup in progress, not as working live telephony.</div>`;
examples.personal=`<div class="doc-callout"><strong>Personal privacy layer.</strong> Vedøy Phone is the app experience for numbers, calls, SMS and account-owned history. The APIs live under Vedøy Developer Portal.</div><h2>Personal endpoints</h2><div class="doc-columns"><div class="doc-mini-card"><strong>Find and buy a number</strong><p>Search provider inventory and review country pricing before purchase.</p><code>GET /v1/numbers/available</code><br/><code>POST /v1/numbers/purchase</code></div><div class="doc-mini-card"><strong>Secure calls &amp; SMS</strong><p>Send an SMS or request a short-lived Voice token with the signed-in user's API session.</p><code>POST /v1/messages</code><br/><code>POST /v1/voice/token</code></div></div><p><a class="doc-cta" href="#phone" data-page="phone">Open Developer Portal Phone APIs →</a> &nbsp; <a class="doc-cta" href="#playground" data-page="playground">Explore local mock examples →</a></p>`;
examples.credits=`<section class="credits-overview"><div class="credits-balance-card"><span class="overline">LOCAL DEMO WALLET</span><strong><span id="credits-page-balance">50</span> <small>Vedøy Credits</small></strong><p>This balance is stored in this browser only. It is not account-backed, transferable, redeemable, or usable with live APIs.</p><span class="service-state">Demo · no purchase available</span></div><div class="credits-explainer"><span class="overline">ONE VEDØY UNIT</span><h2>One balance. Connected services.</h2><p>Vedøy Credits are planned as a common display and budget unit. Vedøy would pay connected providers behind the scenes, then show customers the service, usage, conversion and remaining budget in one ledger.</p><ul><li>AI: show model and token usage</li><li>Phone: itemize calls, SMS and number rent</li><li>Control: monthly budgets, alerts and a pause switch</li></ul></div></section><div class="doc-callout"><strong>Current status:</strong> the browser balance and simulated API deductions are a local demo. They do not sync to Vedøy accounts or call Stripe, Supabase billing, AI providers, Twilio or Telnyx. Do not use them to estimate an invoice.</div><h2>How to build with Vedøy Phone</h2><p>Vedøy Phone is the app. It should request authenticated communications APIs from Vedøy Developer Portal, then show usage and credits from the same customer account.</p><p><a class="doc-cta" href="https://vedoy-phone.vercel.app/developers/" target="_blank" rel="noreferrer">Vedøy Phone app guide ↗</a> &nbsp; <a class="doc-cta" href="https://github.com/leandervedoy/vedoy-phone" target="_blank" rel="noreferrer">Mobile app repository ↗</a></p><h2>Before selling credits</h2><p>Set a published EUR/NOK conversion, define refunds and expiry, persist an auditable server-side ledger, reserve funds atomically before provider requests, reconcile failed calls, and verify tax and consumer terms.</p>`;
 const contentBlock=key==="developer-api"?developerApiDemo():(examples[key]||examples.quickstart)+(key==="services"?cssStudioDemo():"");
 return `<article class="doc-view"><div class="doc-kicker">${p.label}</div><h1>${p.title}</h1><p class="doc-lead">${p.lead}</p>${contentBlock}${apiEstimatePages.has(key)?priceEstimator(key):""}<a class="doc-next" href="#${key==='quickstart'?'authentication':'quickstart'}" data-page="${key==='quickstart'?'authentication':'quickstart'}"><span>CONTINUE READING</span><strong>${key==='quickstart'?'Authentication':'Quickstart'} →</strong></a></article>`;
}
function openPage(key,scroll=true){
 if(!pages[key])return;
 document.body.dataset.page=key;
 breadcrumb.textContent=pages[key].title;
 navLinks.forEach(link=>link.classList.toggle("active",link.dataset.page===key));
  if(key==="overview"){content.innerHTML=initialContent;}else{content.innerHTML=docBody(key);}
  const activeNav=document.querySelector(`.nav-link[data-page="${key}"]`);if(activeNav?.closest(".nav-section"))activeNav.closest(".nav-section").open=true;
  updateCoins();
  addCodeCopyButtons();
  initPriceEstimators();
  initPhoneProvisioner();
 content.classList.remove("page-enter");
 requestAnimationFrame(()=>content.classList.add("page-enter"));
 if(scroll)window.scrollTo({top:0,behavior:"smooth"});
 document.dispatchEvent(new CustomEvent("vedoy-page-change",{detail:{page:key}}));
 }
 function initPriceEstimators(){
  content.querySelectorAll("[data-price-estimator]").forEach(card=>{
   const inputs={volume:card.querySelector('[data-estimate-input="volume"]'),workload:card.querySelector('[data-estimate-input="workload"]'),wage:card.querySelector('[data-estimate-input="wage"]')};
   const money=value=>new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:0}).format(value);
   const update=()=>{const volume=Number(inputs.volume.value),workload=Number(inputs.workload.value),wage=Number(inputs.wage.value),rate=Number(card.dataset.rate),multiplier=Number(card.dataset.multiplier);const api=Math.max(1,volume*rate*(.55+workload/10));const manual=volume*(workload/60)*wage*.08*multiplier;card.querySelector("[data-estimate-volume]").textContent=volume.toLocaleString("en-US");card.querySelector("[data-estimate-workload]").textContent=workload;card.querySelector("[data-estimate-wage]").textContent=wage;card.querySelector("[data-estimate-api]").textContent=money(api);card.querySelector("[data-estimate-manual]").textContent=money(manual);card.querySelector("[data-estimate-saving]").textContent=money(Math.max(0,manual-api));};
   Object.values(inputs).forEach(input=>input.addEventListener("input",update));update();
  });
 }
 function initPhoneProvisioner(){
  const root=content.querySelector("[data-phone-provisioner]");if(!root)return;
  const api="https://vedoy-phone-api.vercel.app",state=root.querySelector("[data-phone-state]"),results=root.querySelector("[data-phone-results]"),form=root.querySelector("[data-phone-search]");
  const setState=(text,kind="info")=>{state.textContent=text;state.dataset.kind=kind;};
  const session=async()=>{const client=window.vedoySupabase;if(!client)throw new Error("Sign in with Vedøy before using Phone.");const {data}=await client.auth.getSession();if(!data.session?.access_token)throw new Error("Sign in with Vedøy before using Phone.");return data.session.access_token;};
  const request=async(path,options={})=>{const token=await session();const response=await fetch(api+path,{...options,headers:{Authorization:"Bearer "+token,"Content-Type":"application/json",...(options.headers||{})}});const payload=await response.json().catch(()=>({message:"The Developer Portal API returned an unreadable response."}));if(!response.ok)throw new Error(payload.message||"Developer Portal API request failed.");return payload;};
  fetch(api+"/health").then(async response=>{const info=await response.json().catch(()=>null);if(response.ok)setState("Developer Portal API is ready.","success");else if(info?.missingConfiguration)setState("Developer Portal API setup is in progress. Purchasing is not available yet.","warning");else setState("Developer Portal API is unavailable. Try again later.","error");}).catch(()=>setState("Could not reach the Developer Portal API.","error"));
  form.addEventListener("submit",async event=>{event.preventDefault();results.innerHTML="<p>Searching carrier inventory…</p>";try{const values=new FormData(form),country=String(values.get("country")),type=String(values.get("type"));const data=await request(`/v1/numbers/available?country=${encodeURIComponent(country)}&type=${encodeURIComponent(type)}`);if(!data.numbers?.length){results.innerHTML="<p>No eligible numbers were returned for this selection.</p>";return;}results.innerHTML=data.numbers.map(number=>`<article class="phone-number-card"><div><strong>${number.friendlyName||number.phoneNumber}</strong><code>${number.phoneNumber}</code><small>${number.capabilities?.voice?"Voice ":""}${number.capabilities?.sms?"SMS":""} · ${number.monthlyPrice||"Price unavailable"} ${number.currency||""} / month</small></div><button class="button-primary" type="button" data-phone-purchase data-phone-number="${number.phoneNumber}" data-phone-country="${number.countryCode}" data-phone-type="${number.numberType}" data-phone-price="${number.monthlyPrice||""}" data-phone-currency="${number.currency||""}">Buy number</button></article>`).join("");setState("Live inventory loaded.","success");}catch(error){results.innerHTML=`<p>${error.message}</p>`;setState(error.message,"error");}});
  results.addEventListener("click",async event=>{const button=event.target.closest("[data-phone-purchase]");if(!button)return;const monthlyPrice=button.dataset.phonePrice,currency=button.dataset.phoneCurrency;if(!monthlyPrice||!currency){toast("This number is missing a verified current price.","error");return;}if(!confirm(`Buy ${button.dataset.phoneNumber} for ${monthlyPrice} ${currency} per month, plus usage?`))return;button.disabled=true;button.textContent="Provisioning…";try{const data=await request("/v1/numbers/purchase",{method:"POST",body:JSON.stringify({phoneNumber:button.dataset.phoneNumber,countryCode:button.dataset.phoneCountry,numberType:button.dataset.phoneType,confirmedMonthlyPrice:monthlyPrice,currency})});button.textContent="Number active ✓";toast(`${data.phoneNumber} is active on your account.`);}catch(error){button.disabled=false;button.textContent="Buy number";toast(error.message,"error");}});
 }
 function addCodeCopyButtons(){
  content.querySelectorAll(".doc-view pre").forEach((block,index)=>{
   if(block.querySelector(".code-copy"))return;
   const button=document.createElement("button");button.className="code-copy";button.type="button";button.textContent="Copy";
   button.setAttribute("aria-label","Copy code example "+(index+1));
   button.addEventListener("click",async()=>{try{const code=block.cloneNode(true);code.querySelector(".code-copy")?.remove();await navigator.clipboard.writeText(code.innerText.trim());button.textContent="Copied ✓";button.dataset.copied="true";}catch{button.textContent="Select code to copy";}window.setTimeout(()=>{button.textContent="Copy";delete button.dataset.copied;},1600);});
   block.append(button);
  });
 }
document.addEventListener("click",e=>{const link=e.target.closest("[data-page]");if(!link)return;e.preventDefault();const key=link.dataset.page;closeMenu();if(missionEntry&&!missionEntry.hidden){leaveMission(key);return;}openPage(key);history.replaceState(null,"",`#${key}`);});
const hash=location.hash.slice(1);if(pages[hash]&&hash!=="overview")openPage(hash,false);

document.addEventListener("click",async e=>{const button=e.target.closest("[data-copy]");if(!button)return;try{await navigator.clipboard.writeText(button.dataset.copy);button.innerHTML='Copied <span>✓</span>';setTimeout(()=>button.innerHTML='Copy <span>▢</span>',1400);}catch{button.innerHTML='Select code';}});
document.addEventListener("click",e=>{if(e.target.closest("[data-topup]")){if(location.hash!=="#credits"){openPage("credits");history.replaceState(null,"","#credits");}toast("Credits are a preview. Purchases are not available yet.","info");return;}const pill=e.target.closest(".flow-pill");if(pill){pill.parentElement.querySelectorAll(".flow-pill").forEach(x=>x.classList.remove("active"));pill.classList.add("active");return;}const run=e.target.closest(".endpoint-run");if(!run)return;const card=run.closest(".endpoint-card"),cost=Number(card.dataset.cost||0),result=card.querySelector(".endpoint-result");if(coins<cost){openPage("credits");history.replaceState(null,"","#credits");toast("This demo wallet is empty. Live top-ups are not available yet.","error");return;}coins-=cost;updateCoins();const id=card.dataset.endpoint;const payload={burner:{number:"+47 48 21 73 09",status:"active",expires_in:3600},sms:{message_id:"sms_mock_"+Date.now(),status:"delivered"},esim:{iccid:"8947000000001234567",qr_payload:"LPA:1$vedoy.mock$eSIM-1GB",status:"ready"},sip:{trunk_id:"trunk_eu_"+Date.now().toString().slice(-6),region:card.querySelector("select")?.value||"Europe",status:"provisioned"},ivr:{flow:[{key:"1",route:"sales"},{key:"2",route:"support"}],status:"saved"},ais:{vessels:[{mmsi:"257123400",lat:59.91,lon:10.73},{mmsi:"257894100",lat:59.88,lon:10.76},{mmsi:"258004200",lat:59.94,lon:10.69}],scanned_at:new Date().toISOString()}};result.textContent=JSON.stringify({ok:true,data:payload[id]},null,2);card.classList.add("ran");toast(`Demo success: -${cost} Vedøy Credits`);});
document.addEventListener("click",e=>{const demo=e.target.closest("[data-demo-key]");if(!demo)return;demo.textContent="Demo key generated ✓";demo.disabled=true;toast("Demo only — no real secret was created");});
const search=document.querySelector("#search-input"),results=document.querySelector("#search-results");
function runSearch(){const q=search.value.trim().toLowerCase();if(!q){results.hidden=true;return;}const matches=Object.entries(pages).filter(([key,p])=>(`${p.title} ${p.label} ${p.lead} ${key}`).toLowerCase().includes(q)).slice(0,6);results.innerHTML=matches.map(([key,p])=>`<a href="#${key}" data-result="${key}">${p.title}<span style="float:right;color:#9aa39b">↗</span></a>`).join("")||'<a href="#">No matching docs</a>';results.hidden=false;results.querySelectorAll("[data-result]").forEach(a=>a.addEventListener("click",e=>{e.preventDefault();openPage(a.dataset.result);history.replaceState(null,"",`#${a.dataset.result}`);results.hidden=true;search.value="";}));}
search.addEventListener("input",runSearch);document.addEventListener("click",e=>{if(!e.target.closest(".sidebar-search-wrap"))results.hidden=true;});document.addEventListener("keydown",e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();search.focus();}if(e.key==="Escape"){results.hidden=true;closeMenu(true);}});
